from g import *
S = SETUP_STD
# 13
A('13', 'voice-call-summary', 'After-hours call summary (Vapi / Retell / Twilio)', 'Support', 'Receives the end-of-call report from an AI voice agent, extracts caller, intent and callback need, and logs it and alerts you when a callback is requested.',
 ('webhook', 'call-ended'), [cfg(), norm("const m=b.message||b;return [{json:{phone:m.customer&&m.customer.number||m.from||'unknown',transcript:String(m.transcript||'').slice(0,6000),duration:m.durationSeconds||0}}];"),
  ai('Summarise call', 'Summarise a business phone call. JSON: {"caller_name":"","reason":"","outcome":"booked|callback|info|spam","callback_needed":true,"summary":""}', "JSON.stringify($json)"),
  row('Row: call', "return [{json:{date:new Date().toISOString(),phone:j.phone,name:j.ai.caller_name,reason:j.ai.reason,outcome:j.ai.outcome,summary:j.ai.summary}}];"), sheet_append('Log call'),
  iff("$('Parse: Summarise call').first().json.ai.callback_needed", [slack('Alert: callback needed', "'Callback needed: ' + $('Parse: Summarise call').first().json.phone + ' - ' + $('Parse: Summarise call').first().json.ai.summary")])],
 {'message': {'customer': {'number': '+15550001111'}, 'transcript': 'Hi, this is Tom, my AC is out, please call me back tomorrow.', 'durationSeconds': 64}}, S, {'AI: Summarise call': {'caller_name': 'Tom', 'reason': 'AC repair', 'outcome': 'callback', 'callback_needed': True, 'summary': 'Tom needs AC repair callback.'}}, ['Log call', 'Alert: callback needed'])
# 14
A('14', 'nps-detractor-alert', 'NPS survey scorer and detractor alert', 'Support', 'Scores each NPS response, alerts Slack on detractors with the comment, thanks promoters and asks for a referral, and logs all.',
 ('webhook', 'nps'), [cfg(referralLink='https://yourdomain.com/refer'), norm("const s=Number(b.score);return [{json:{email:b.email,name:b.name||'there',score:s,comment:b.comment||'',type:s>=9?'promoter':s>=7?'passive':'detractor'}}];"),
  row('Row: nps', "return [{json:{date:new Date().toISOString(),email:j.email,score:j.score,type:j.type,comment:j.comment}}];"), sheet_append('Log NPS'),
  iff("$('Normalize').first().json.type === 'detractor'", [slack('Alert: detractor', "'Detractor ' + $('Normalize').first().json.email + ' scored ' + $('Normalize').first().json.score + ': ' + $('Normalize').first().json.comment")],
   [iff("$('Normalize').first().json.type === 'promoter'", [mail('Thank promoter', "$('Normalize').first().json.email", "'Thank you!'", "'Hi ' + $('Normalize').first().json.name + ', thank you for the great score. Know someone who would love us? ' + $('Config').first().json.referralLink")])])],
 {'email': 'kim@x.com', 'name': 'Kim', 'score': 3, 'comment': 'Onboarding was confusing'}, S, {}, ['Log NPS', 'Alert: detractor'], ['Thank promoter'])
# 15
A('15', 'refund-handler', 'Refund request handler', 'Support', 'Applies your refund policy as rules first (window and amount), auto-approves small eligible refunds via the Stripe API and sends bigger ones to Slack for a human.',
 ('webhook', 'refund-request'), [cfg(refundWindowDays='30', autoApproveUnder='50'), norm("const c=$('Config').first().json;const age=Math.floor((Date.now()-new Date(b.purchased_at).getTime())/864e5);return [{json:{email:b.email,charge:b.charge_id,amount:Number(b.amount),reason:b.reason||'',age,eligible:age<=Number(c.refundWindowDays),auto:Number(b.amount)<Number(c.autoApproveUnder)}}];"),
  iff('$json.eligible && $json.auto', [http('Stripe refund', 'POST', 'https://api.stripe.com/v1/refunds', None, 'Stripe (Header Auth: Authorization = Bearer sk_live_...)', form={'charge': '$json.charge'}), mail('Confirm refund', "$('Normalize').first().json.email", "'Your refund is on the way'", "'We refunded ' + $('Normalize').first().json.amount.toFixed(2) + '. It appears in 5-10 days.'")],
   [slack('Review: refund', "'Refund review needed: ' + $json.email + ' amount ' + $json.amount + ', ' + $json.age + ' days old, eligible=' + $json.eligible + '. Reason: ' + $json.reason")])],
 {'email': 'bo@x.com', 'charge_id': 'ch_123', 'amount': 29, 'purchased_at': '__AGO7__', 'reason': 'Not what I expected'}, S, {}, ['Stripe refund', 'Confirm refund'], ['Review: refund'])
# 16
A('16', 'review-reply-drafter', 'Google review reply drafter', 'Marketing', 'New review webhook (from a reviews tool) becomes an AI-drafted public reply in your brand voice, sent to Slack for one-click approval. Negative reviews are flagged.',
 ('webhook', 'new-review'), [cfg(brandVoice='warm, concise, professional'), norm("return [{json:{author:b.author||'Customer',rating:Number(b.rating),text:String(b.text||''),platform:b.platform||'Google'}}];"),
  ai('Reply', "Draft a public reply to a customer review. Brand voice given. Never offer refunds publicly. JSON: {\"reply\":\"\"}", "JSON.stringify({voice:$('Config').first().json.brandVoice,review:$json})"),
  iff('$json.rating <= 3', [slack('Alert: negative review', "'NEGATIVE ' + $json.rating + '-star review by ' + $json.author + ': ' + $json.text + '\\nDraft reply: ' + $json.ai.reply")], [slack('Draft: positive review reply', "$json.rating + '-star review by ' + $json.author + '. Suggested reply: ' + $json.ai.reply")])],
 {'author': 'Marta', 'rating': 2, 'text': 'Waited 40 minutes for my order.'}, S, {'AI: Reply': {'reply': 'Thank you for telling us, Marta...'}}, ['Alert: negative review'], ['Draft: positive review reply'])
# 17
A('17', 'dispute-alert', 'Stripe dispute alert and evidence checklist', 'Finance', 'Instantly alerts you to a new Stripe dispute with the deadline and a tailored evidence checklist so you never miss the response window.',
 ('webhook', 'stripe-dispute'), [cfg(), norm("const d=(b.data&&b.data.object)||b;return [{json:{id:d.id,amount:Number(d.amount||0)/100,reason:d.reason||'general',due:d.evidence_details&&d.evidence_details.due_by?new Date(d.evidence_details.due_by*1000).toISOString().slice(0,10):'check Stripe'}}];"),
  code('Checklist', "const j=$input.first().json;const base=['Order confirmation and receipt','Customer communication','Refund policy as shown at checkout'];const extra={fraudulent:['IP address and device log','Proof of delivery or usage'],product_not_received:['Tracking number and delivery confirmation'],subscription_canceled:['Cancellation policy and sign-up consent'],duplicate:['Both charge IDs and what each covered']}[j.reason]||[];return [{json:{...j,checklist:base.concat(extra).map((x,i)=>(i+1)+'. '+x).join('\\n')}}];"),
  slack('Alert: dispute', "'DISPUTE ' + $json.id + ' for $' + $json.amount.toFixed(2) + ' (' + $json.reason + '). Respond by ' + $json.due + '.\\n' + $json.checklist")],
 {'type': 'charge.dispute.created', 'data': {'object': {'id': 'dp_1', 'amount': 4900, 'reason': 'fraudulent', 'evidence_details': {'due_by': 1799000000}}}}, S, {}, ['Alert: dispute'])
# 18
A('18', 'dunning-emails', 'Failed payment dunning sequence', 'Finance', 'When a subscription payment fails it emails the customer a payment-update link, waits and retries messaging on day 3 and day 7, and tells you if it is still unpaid.',
 ('webhook', 'payment-failed'), [cfg(billingPortal='https://billing.stripe.com/p/login/YOUR_LINK'), norm("const o=(b.data&&b.data.object)||b;return [{json:{email:o.customer_email,name:o.customer_name||'there',amount:Number(o.amount_due||0)/100,invoice:o.id}}];"),
  mail('Dunning day 0', '$json.email', "'Your payment did not go through'", "'Hi ' + $json.name + ', your payment of $' + $json.amount.toFixed(2) + ' failed. Update your card: ' + $('Config').first().json.billingPortal"),
  wait('Wait 3 days', 3, 'days'), mail('Dunning day 3', "$('Normalize').first().json.email", "'Reminder: payment failed'", "'Friendly reminder to update your card: ' + $('Config').first().json.billingPortal"),
  wait('Wait 4 days', 4, 'days'), slack('Alert: still unpaid', "'Invoice ' + $('Normalize').first().json.invoice + ' still unpaid after 7 days for ' + $('Normalize').first().json.email")],
 {'type': 'invoice.payment_failed', 'data': {'object': {'id': 'in_1', 'customer_email': 'zed@x.com', 'customer_name': 'Zed', 'amount_due': 4900}}}, S, {}, ['Dunning day 0', 'Dunning day 3', 'Alert: still unpaid'])
# 19
A('19', 'invoice-chaser', 'Overdue invoice chaser', 'Finance', 'Daily scan of your invoice sheet. Sends a polite reminder at 1, 7 and 14 days overdue and a firm notice at 30; summarises the total outstanding to Slack.',
 cron(8, 15), [cfg(), sheet_read('Read invoices'),
  code('Find overdue', "const now=Date.now();const out=[];let total=0;for(const it of $input.all()){const r=it.json;if(String(r.status).toLowerCase()==='paid')continue;const late=Math.floor((now-new Date(r.due).getTime())/864e5);if(late>0){total+=Number(r.amount||0);if([1,7,14,30].includes(late))out.push({json:{number:r.number,client:r.client,email:r.email,amount:Number(r.amount),late,tone:late>=30?'firm':'polite'}});}}return out.length?out:[{json:{none:true,total}}];"),
  iff('!$json.none', [mail('Send reminder', '$json.email', "'Invoice ' + $json.number + ' is ' + $json.late + ' days overdue'", "'Hi ' + $json.client + ',\\n\\n' + ($json.tone==='firm' ? 'Invoice ' + $json.number + ' for $' + $json.amount.toFixed(2) + ' is now ' + $json.late + ' days overdue. Please pay this week to avoid late fees.' : 'A friendly reminder that invoice ' + $json.number + ' for $' + $json.amount.toFixed(2) + ' was due ' + $json.late + ' days ago.') + '\\n\\n' + $('Config').first().json.businessName")])],
 {}, ['Sheet columns: number, client, email, amount, due (YYYY-MM-DD), status.'] + S[1:], {'Read invoices': [{'number': '1002', 'client': 'Brightside', 'email': 'b@b.com', 'amount': '1440', 'due': '__AGO7__', 'status': 'Sent'}, {'number': '1001', 'client': 'Done', 'email': 'd@d.com', 'amount': '100', 'due': '__AGO7__', 'status': 'Paid'}]}, ['Send reminder'])
# 20
A('20', 'receipt-extractor', 'Receipt and expense extractor (AI vision)', 'Finance', 'Send a receipt photo URL (from email, Telegram or a form); AI reads vendor, date, total and category and appends a clean row to your expense sheet.',
 ('webhook', 'receipt'), [cfg(), norm("return [{json:{image:b.image_url,who:b.who||''}}];"),
  N('AI: Read receipt', 'n8n-nodes-base.httpRequest', 4.2, {'method': 'POST', 'url': "={{ $('Config').first().json.aiBaseUrl }}", 'authentication': 'genericCredentialType', 'genericAuthType': 'httpHeaderAuth', 'sendBody': True, 'specifyBody': 'json', 'jsonBody': "={{ JSON.stringify({model:$('Config').first().json.aiModel,response_format:{type:'json_object'},messages:[{role:'system',content:'Extract from the receipt image. JSON: {\"vendor\":\"\",\"date\":\"YYYY-MM-DD\",\"total\":0,\"tax\":0,\"category\":\"meals|software|travel|supplies|other\"}'},{role:'user',content:[{type:'image_url',image_url:{url:$json.image}}]}]}) }}", 'options': {}}, {'httpHeaderAuth': {'id': '', 'name': 'AI API key (Header Auth)'}}),
  code('Parse: Read receipt', "const t=$input.first().json.choices[0].message.content;let o;try{o=JSON.parse(t)}catch(e){o={}}return [{json:{...$('Normalize').first().json,vendor:o.vendor||'Unknown',date:o.date||new Date().toISOString().slice(0,10),total:Number(o.total||0),tax:Number(o.tax||0),category:o.category||'other'}}];"),
  sheet_append('Append expense')],
 {'image_url': 'https://example.com/receipt.jpg', 'who': 'Alex'}, ['Use a vision-capable model in Config (for example gpt-4o-mini).'] + S[1:], {'AI: Read receipt': {'vendor': 'Blue Bottle', 'date': '2026-11-20', 'total': 14.5, 'tax': 1.1, 'category': 'meals'}}, ['Append expense'])
# 21
A('21', 'daily-revenue-slack', 'Daily revenue snapshot to Slack', 'Finance', 'Every morning pulls yesterday\'s Stripe charges and posts revenue, order count, average order and refunds to Slack.',
 cron(7, 45), [cfg(), code('Date range', "const e=new Date();e.setUTCHours(0,0,0,0);const s=new Date(e.getTime()-864e5);return [{json:{gte:Math.floor(s.getTime()/1000),lt:Math.floor(e.getTime()/1000),label:s.toISOString().slice(0,10)}}];"),
  http('Stripe charges', 'GET', 'https://api.stripe.com/v1/charges', None, 'Stripe (Header Auth: Authorization = Bearer sk_live_...)', query="{limit:100,'created[gte]':$json.gte,'created[lt]':$json.lt}"),
  code('Summarise', "const d=$input.first().json.data||[];const paid=d.filter(c=>c.paid&&!c.refunded);const rev=paid.reduce((a,c)=>a+c.amount-(c.amount_refunded||0),0)/100;const refunds=d.reduce((a,c)=>a+(c.amount_refunded||0),0)/100;return [{json:{date:$('Date range').first().json.label,orders:paid.length,revenue:rev,aov:paid.length?rev/paid.length:0,refunds}}];"),
  slack('Post to Slack', "'Revenue ' + $json.date + ': $' + $json.revenue.toFixed(2) + ' from ' + $json.orders + ' orders (avg $' + $json.aov.toFixed(2) + '), refunds $' + $json.refunds.toFixed(2)")],
 {}, ['Stripe credential must be a restricted key with read access to charges.'] + S[1:], {'Stripe charges': {'data': [{'amount': 5000, 'paid': True, 'refunded': False}, {'amount': 3000, 'paid': True, 'refunded': False, 'amount_refunded': 1000}]}}, ['Post to Slack'])
# 22
A('22', 'weekly-cashflow-digest', 'Weekly cash-flow digest', 'Finance', 'Reads your ledger sheet every Monday, totals last week income, expenses and net, flags the biggest category and emails a plain-English summary.',
 weekly(1, 8), [cfg(), sheet_read('Read ledger'),
  code('Totals', "const since=Date.now()-7*864e5;let inc=0,exp=0;const cat={};for(const it of $input.all()){const r=it.json;const t=new Date(r.date).getTime();if(isNaN(t)||t<since)continue;const a=Number(r.amount||0);if(String(r.type).toLowerCase()==='income')inc+=a;else{exp+=a;cat[r.category]=(cat[r.category]||0)+a;}}const top=Object.entries(cat).sort((a,b)=>b[1]-a[1])[0]||['none',0];return [{json:{inc,exp,net:inc-exp,top:top[0],topAmt:top[1]}}];"),
  mail('Email digest', "$('Config').first().json.emailTo", "'Weekly cash flow: net $' + $json.net.toFixed(2)", "'Income $' + $json.inc.toFixed(2) + '\\nExpenses $' + $json.exp.toFixed(2) + '\\nNet $' + $json.net.toFixed(2) + '\\nBiggest expense: ' + $json.top + ' ($' + $json.topAmt.toFixed(2) + ')'")],
 {}, ['Sheet columns: date, type (Income/Expense), category, amount.'] + S[1:], {'Read ledger': [{'date': '__AGO3__', 'type': 'Income', 'category': 'Sales', 'amount': '2000'}, {'date': '__AGO3__', 'type': 'Expense', 'category': 'Ads', 'amount': '500'}]}, ['Email digest'])
# 23
A('23', 'churn-exit-survey', 'Cancellation exit survey and win-back', 'Finance', 'When a subscription is cancelled it emails a one-question survey, then AI classifies the reply and either offers a pause/discount or alerts you about a product issue.',
 ('webhook', 'cancelled'), [cfg(winbackOffer='3 months at 30% off'), norm("const o=(b.data&&b.data.object)||b;return [{json:{email:o.customer_email||b.email,name:o.customer_name||'there',plan:o.plan||'your plan',reason:b.reason||''}}];"),
  mail('Exit survey', '$json.email', "'Sorry to see you go'", "'Hi ' + $json.name + ', would you tell us in one line why you cancelled ' + $json.plan + '? Just reply to this email.'"),
  iff('$json.reason', [N('AI: Classify reason', 'n8n-nodes-base.httpRequest', 4.2, {'method': 'POST', 'url': "={{ $('Config').first().json.aiBaseUrl }}", 'authentication': 'genericCredentialType', 'genericAuthType': 'httpHeaderAuth', 'sendBody': True, 'specifyBody': 'json', 'jsonBody': "={{ JSON.stringify({model:$('Config').first().json.aiModel,response_format:{type:'json_object'},messages:[{role:'system',content:'Classify the cancellation reason. JSON: {\"category\":\"price|missing_feature|bug|no_need|competitor|other\",\"winback\":true}'},{role:'user',content:$('Normalize').first().json.reason}]}) }}", 'options': {}}, {'httpHeaderAuth': {'id': '', 'name': 'AI API key (Header Auth)'}}),
   code('Parse: Classify reason', "const t=$input.first().json.choices[0].message.content;let o;try{o=JSON.parse(t)}catch(e){o={category:'other',winback:false}}return [{json:{...$('Normalize').first().json,cat:o.category,winback:!!o.winback}}];"),
   iff("$json.cat === 'price' || $json.winback", [mail('Win-back offer', '$json.email', "'A better offer for you'", "'Hi ' + $json.name + ', we would love you back: ' + $('Config').first().json.winbackOffer + '.'")], [slack('Alert: product feedback', "'Churn reason (' + $json.cat + '): ' + $json.reason")])])],
 {'customer_email': 'ana@x.com', 'customer_name': 'Ana', 'plan': 'Pro', 'reason': 'Too expensive for what I use'}, S, {'AI: Classify reason': {'category': 'price', 'winback': True}}, ['Exit survey', 'Win-back offer'], ['Alert: product feedback'])
# 24
A('24', 'subscription-renewal-reminder', 'Renewal reminder 7 days before billing', 'Finance', 'Daily scan of your subscriber sheet; emails customers 7 days before renewal (a legal best practice for auto-renew) and a Slack digest of upcoming renewals and MRR.',
 cron(9), [cfg(), sheet_read('Read subscribers'),
  code('Due in 7 days', "const out=[];let mrr=0;for(const it of $input.all()){const r=it.json;if(String(r.status).toLowerCase()!=='active')continue;mrr+=Number(r.price||0);const d=Math.ceil((new Date(r.renews_on).getTime()-Date.now())/864e5);if(d===7)out.push({json:{name:r.name,email:r.email,price:Number(r.price),date:r.renews_on,mrr}});}return out.length?out:[{json:{none:true,mrr}}];"),
  iff('!$json.none', [mail('Renewal notice', '$json.email', "'Your subscription renews on ' + $json.date", "'Hi ' + $json.name + ', your plan renews on ' + $json.date + ' for $' + $json.price.toFixed(2) + '. Manage or cancel any time in your account.'"), slack('Digest: renewals', "'Renewal notice sent to ' + $json.email + '. Active MRR $' + $json.mrr.toFixed(2)")])],
 {}, ['Sheet columns: name, email, status, price, renews_on (YYYY-MM-DD).'] + S[1:], {'Read subscribers': [{'name': 'Kay', 'email': 'k@x.com', 'status': 'Active', 'price': '29', 'renews_on': '__PLUS7__'}, {'name': 'Lee', 'email': 'l@x.com', 'status': 'Active', 'price': '49', 'renews_on': '2999-01-01'}]}, ['Renewal notice', 'Digest: renewals'])
